export const getMoviesRecommendationsRoute = createRoute({
  method: 'get',
  path: '/Movies/Recommendations',
  tags: ['Movies'],
  summary: 'Gets movie recommendations.',
  operationId: 'GetMovieRecommendations',
  request: {
    query: z.object({
      userId: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.uuid().nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            description: 'Optional. Filter by user id, and attach user data.',
            in: 'query',
            name: 'userId',
            schema: {
              description: 'Optional. Filter by user id, and attach user data.',
              format: 'uuid',
              nullable: true,
              type: 'string',
            },
            required: false,
          },
          description: 'Optional. Filter by user id, and attach user data.',
        }),
      parentId: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.uuid().nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Specify this to localize the search to a specific item or folder. Omit to use the root.',
            in: 'query',
            name: 'parentId',
            schema: {
              description:
                'Specify this to localize the search to a specific item or folder. Omit to use the root.',
              format: 'uuid',
              nullable: true,
              type: 'string',
            },
            required: false,
          },
          description:
            'Specify this to localize the search to a specific item or folder. Omit to use the root.',
        }),
      fields: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(ItemFieldsSchema),
        )
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            description: 'Optional. The fields to return.',
            in: 'query',
            name: 'fields',
            schema: {
              description: 'Optional. The fields to return.',
              items: { $ref: '#/components/schemas/ItemFields' },
              nullable: true,
              type: 'array',
            },
            required: false,
          },
          description: 'Optional. The fields to return.',
        }),
      categoryLimit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(5)
        .exactOptional()
        .openapi({
          param: {
            description: 'The max number of categories to return.',
            in: 'query',
            name: 'categoryLimit',
            schema: {
              default: 5,
              description: 'The max number of categories to return.',
              format: 'int32',
              type: 'integer',
            },
            required: false,
          },
          description: 'The max number of categories to return.',
        }),
      itemLimit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(8)
        .exactOptional()
        .openapi({
          param: {
            description: 'The max number of items to return per category.',
            in: 'query',
            name: 'itemLimit',
            schema: {
              default: 8,
              description: 'The max number of items to return per category.',
              format: 'int32',
              type: 'integer',
            },
            required: false,
          },
          description: 'The max number of items to return per category.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Movie recommendations returned.',
      content: {
        'application/json': { schema: z.array(RecommendationDtoSchema) },
        'application/json; profile="CamelCase"': { schema: z.array(RecommendationDtoSchema) },
        'application/json; profile="PascalCase"': { schema: z.array(RecommendationDtoSchema) },
      },
    },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
  },
  security: [{ CustomAuthentication: [] }],
})

