export const postSessionsSessionIdMessageRoute = createRoute({
  method: 'post',
  path: '/Sessions/{sessionId}/Message',
  tags: ['Session'],
  summary: 'Issues a command to a client to display a message to the user.',
  operationId: 'SendMessageCommand',
  request: {
    params: z.object({
      sessionId: z
        .string()
        .openapi({
          param: {
            description: 'The session id.',
            in: 'path',
            name: 'sessionId',
            required: true,
            schema: { description: 'The session id.', type: 'string' },
          },
          description: 'The session id.',
        }),
    }),
    query: z.object({
      text: z
        .string()
        .openapi({
          param: {
            description: 'The message test.',
            in: 'query',
            name: 'text',
            required: true,
            schema: { description: 'The message test.', type: 'string' },
          },
          description: 'The message test.',
        }),
      header: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            description: 'The message header.',
            in: 'query',
            name: 'header',
            schema: { description: 'The message header.', nullable: true, type: 'string' },
            required: false,
          },
          description: 'The message header.',
        }),
      timeoutMs: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The message timeout. If omitted the user will have to confirm viewing the message.',
            in: 'query',
            name: 'timeoutMs',
            schema: {
              description:
                'The message timeout. If omitted the user will have to confirm viewing the message.',
              format: 'int64',
              nullable: true,
              type: 'integer',
            },
            required: false,
          },
          description:
            'The message timeout. If omitted the user will have to confirm viewing the message.',
        }),
    }),
  },
  responses: {
    204: { description: 'Message sent.' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
  },
  security: [{ CustomAuthentication: [] }],
})

